"""Erzeugt trainer/content/listening.json und speaking.json (Batch 1).
Konvention: richtige Antwort steht im Quelltext zuerst; die Position wird rotierend auf A–D verteilt."""
import json, random, pathlib
random.seed(11)
OUT = pathlib.Path(__file__).resolve().parent.parent / "content"
POS = [1]
def mc(q, correct, wrong, why):
    a = POS[0] % 4; POS[0] += 1
    rest = wrong[:]; random.shuffle(rest); rest.insert(a, correct)
    return {"q": q, "options": rest, "answer": a, "why": why}

CHOOSE = []
def ch(id, level, voice, prompt, correct, wrong, why):
    m = mc("", correct, wrong, why); CHOOSE.append({"id": id, "level": level, "voice": voice, "prompt": prompt, "options": m["options"], "answer": m["answer"], "why": why})

